t.script:
document.addEventListener('DOMContentLoaded', function() {
    const selectAll = document.getElementById('select_all_requests');
    const checkboxes = document.querySelectorAll('.request_checkbox');
    const bulkContainer = document.getElementById('bulk_actions_container');
    const countSpans = document.querySelectorAll('.selected_count');
    const btnApprove = document.getElementById('btn_bulk_approve');
    const btnRefuse = document.getElementById('btn_bulk_refuse');

    function updateUI() {
        const selected = document.querySelectorAll('.request_checkbox:checked');
        const count = selected.length;

        if (count > 0) {
            bulkContainer.classList.remove('d-none');
            countSpans.forEach(s => s.innerText = count);
        } else {
            bulkContainer.classList.add('d-none');
        }
    }

    if (selectAll) {
        selectAll.addEventListener('change', function() {
            checkboxes.forEach(cb => {
                if (!cb.disabled) cb.checked = selectAll.checked;
            });
            updateUI();
        });
    }

    checkboxes.forEach(cb => {
        cb.addEventListener('change', updateUI);
    });

    async function performBulkAction(action) {
        const selectedIds = Array.from(document.querySelectorAll('.request_checkbox:checked')).map(cb => parseInt(cb.value));
        if (selectedIds.length === 0) return;

        if (!confirm('Are you sure you want to ' + action + ' ' + selectedIds.length + ' request(s)?')) return;

        // Disable buttons
        btnApprove.disabled = true;
        btnRefuse.disabled = true;

        try {
            const response = await fetch('/my/travel/bulk_action', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRF-Token': odoo.csrf_token,
                },
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    params: {
                        request_ids: selectedIds,
                        action: action
                    }
                })
            });
            const result = await response.json();
            if (result.result && result.result.success) {
                window.location.reload();
            } else {
                alert('Error processing requests');
            }
        } catch (err) {
            console.error(err);
            alert('An unexpected error occurred');
        } finally {
            btnApprove.disabled = false;
            btnRefuse.disabled = false;
        }
    }

    if (btnApprove) btnApprove.addEventListener('click', () => performBulkAction('approve'));
    if (btnRefuse) btnRefuse.addEventListener('click', () => performBulkAction('refuse'));
});

document.addEventListener('DOMContentLoaded', function() {
    const cols = ['fare', 'hotel', 'meals', 'taxi', 'laundry', 'telephone', 'other', 'daily'];
    const rowCount = 7;

    function performCalculation() {
        let grandTotal = 0.0;
        let colTotals = { fare:0, hotel:0, meals:0, taxi:0, laundry:0, telephone:0, other:0, daily:0 };

        for(let i=1; i<=rowCount; i++) {
            let rowTotal = 0.0;
            cols.forEach(col => {
                let input = document.querySelector(`input[name="${col}_${i}"]`);
                let val = parseFloat(input.value) || 0;
                rowTotal += val;
                colTotals[col] += val;
            });
            document.getElementById(`row_total_${i}`).innerText = rowTotal.toFixed(2);
            grandTotal += rowTotal;
        }

        cols.forEach(col => {
            document.getElementById(`col_total_${col}`).innerText = colTotals[col].toFixed(2);
        });

        document.getElementById('grand_total_col').innerText = grandTotal.toFixed(2);
        document.getElementById('summary_total_expense').innerText = grandTotal.toFixed(2);
        document.getElementById('total_expense_input').value = grandTotal.toFixed(2);

        let adv = parseFloat(document.getElementById('input_advance').value) || 0;
        let direct = parseFloat(document.getElementById('input_items_direct').value) || 0;

        let balance = grandTotal - adv - direct;
        document.getElementById('summary_balance_due').innerText = balance.toFixed(2);
    }

    // Trigger initial calculation
    performCalculation();

    document.querySelectorAll('.calc-input, .calc-input-summary').forEach(inp => {
        inp.addEventListener('change', performCalculation);
    });

    document.querySelectorAll('.calc-btn-row').forEach(btn => {
        btn.addEventListener('click', performCalculation);
    });
});
